g.ns22:text:
Cammino (II)
\begin{lstlisting}
@pre
assume l $\le$ u;
m := (l + u) div 2;
assume a[m] = e;
rv := true;
@post
\end{lstlisting}

Cammino (III)
\begin{lstlisting}
@pre
assume l $\le$ u;
m := (l + u) div 2;
assume a[m] $\ne$ e;
assume a[m] < e;
@R1
\end{lstlisting}

Cammino (IV)
\begin{lstlisting}
@pre
assume l $\le$ u;
m:= (l + u) div 2;
assume a[m] $\ne$ e;
assume a[m] < e;
assume $v1 \iff \exists i \colon m+1 \le i \land i \le u \land a[i] = e;$
rv := v1;
@post
\end{lstlisting}
